struct FailingGate { calls: usize, fail_at: usize }

impl AllocationGate for FailingGate {
    fn permit(&mut self, _requested_bytes: usize) -> Result<(), BaseStatus> {
        let call = self.calls;
        self.calls += 1;
        if call == self.fail_at { Err(BaseStatus::OutOfMemory) } else { Ok(()) }
    }
}

#[test]
fn configuration_and_fallible_bounded_allocations() {
    for config in [QueueConfig { capacity: 0, workers: 1 },
        QueueConfig { capacity: 65, workers: 1 }, QueueConfig { capacity: 1, workers: 0 },
        QueueConfig { capacity: 1, workers: 5 }] {
        assert_eq!(TaskQueue::new(config).unwrap_err(), QueueError::Invalid);
    }
    for fail_at in 0..5 {
        let mut gate = FailingGate { calls: 0, fail_at };
        assert_eq!(TaskQueue::with_allocation_gate(QueueConfig { capacity: 2, workers: 1 }, &mut gate)
            .err().unwrap(), QueueError::NoMemory);
        assert_eq!(gate.calls, fail_at + 1);
    }
    let q = queue(64, 4);
    assert_eq!(q.capacity(), 64);
    q.shutdown();
}

#[test]
fn worker_start_failure_stops_and_joins_started_workers() {
    let mut gate = FailingGate { calls: 0, fail_at: usize::MAX };
    let mut starts = 0;
    let result = TaskQueue::with_allocation_gate_and_spawn(
        QueueConfig { capacity: 2, workers: 2 }, &mut gate,
        |shared| {
            if starts == 1 {
                starts += 1;
                Err(std::io::Error::other("injected worker-start failure"))
            } else {
