}

#[test]
fn status_priority_duplicate_full_stale_and_stopped() {
    let q = queue(2, 1);
    let (entered_tx, entered_rx) = mpsc::channel();
    let (release_tx, release_rx) = mpsc::channel();
    enqueue(&q, 1, 1, move |_| { entered_tx.send(()).unwrap(); receive(&release_rx); TaskOutput::success(1) }).unwrap();
    receive(&entered_rx);
    enqueue(&q, 2, 1, |_| TaskOutput::success(2)).unwrap();
    let duplicate = enqueue(&q, 2, 2, |_| TaskOutput::success(0)).unwrap_err();
    assert_eq!(duplicate.status, QueueError::Duplicate);
    assert_eq!(enqueue(&q, 3, 1, |_| TaskOutput::success(0)).unwrap_err().status, QueueError::Full);
    assert_eq!(enqueue(&q, 3, 2, |_| TaskOutput::success(0)).unwrap_err().status, QueueError::Stale);
    release_tx.send(()).unwrap();
    q.shutdown();
    assert_eq!(enqueue(&q, 0, 1, |_| TaskOutput::success(0)).unwrap_err().status, QueueError::Invalid);
    assert_eq!(enqueue(&q, 5, 1, |_| TaskOutput::success(0)).unwrap_err().status, QueueError::Stopped);
    assert_eq!(q.cancel(99), Err(QueueError::NotFound));
}

#[test]
fn rejected_submission_returns_callback_and_context() {
    let q = queue(1, 1);
    let drops = Arc::new(AtomicUsize::new(0));
    let capture = Arc::clone(&drops);
    enqueue(&q, 1, 1, move |_| { let _keep = capture; TaskOutput::success(1) }).unwrap();
    let capture = CountDrop(Arc::clone(&drops));
    let error = enqueue(&q, 1, 1, move |_| { let _keep = capture; TaskOutput::success(2) }).unwrap_err();
    assert_eq!(error.status, QueueError::Duplicate);
    assert_eq!(drops.load(Ordering::SeqCst), 0);
    drop(error.callback);
    assert_eq!(drops.load(Ordering::SeqCst), 1);

    let context = Arc::new(String::from("owned"));
    let callback_context = Arc::clone(&context);
    let shared_error = q.submit(1, 1, TaskCallback::new((), move |_, _| {
        assert_eq!(callback_context.as_str(), "owned");
        TaskOutput::success(3)
    })).unwrap_err();
    assert_eq!(shared_error.status, QueueError::Duplicate);
    drop(shared_error.callback);
    assert_eq!(Arc::strong_count(&context), 1);
    q.shutdown();
}

struct ReentrantDrop(TaskQueue, Arc<AtomicUsize>, Arc<Mutex<Option<TaskResult>>>);

impl Drop for ReentrantDrop {
    fn drop(&mut self) {
        *lock(&self.2) = self.0.poll();
        self.1.fetch_add(1, Ordering::SeqCst);
    }
}

struct ReentrantShutdown(TaskQueue);

impl Drop for ReentrantShutdown {
    fn drop(&mut self) { self.0.shutdown(); }
}

#[test]
fn queued_cancel_drops_owned_context_once_outside_queue_lock() {
    let q = queue(2, 1);
    let (entered_tx, entered_rx) = mpsc::channel();
    let (release_tx, release_rx) = mpsc::channel();
    let (returned_tx, returned_rx) = mpsc::channel();
    enqueue(&q, 10, 1, move |_| {
        entered_tx.send(()).unwrap();
        receive(&release_rx);
        returned_tx.send(()).unwrap();
        TaskOutput::success(10)
    }).unwrap();
    receive(&entered_rx);
    let drops = Arc::new(AtomicUsize::new(0));
    let reentrant_result = Arc::new(Mutex::new(None));
    let guard = ReentrantDrop(q.clone(), Arc::clone(&drops), Arc::clone(&reentrant_result));
    enqueue_owned(&q, 11, 1, guard, |_, _| TaskOutput::success(11)).unwrap();
    assert_eq!(q.cancel(11), Ok(()));
    release_tx.send(()).unwrap();
    receive(&returned_rx);
    let deadline = std::time::Instant::now() + Duration::from_secs(3);
    while drops.load(Ordering::SeqCst) == 0 && std::time::Instant::now() < deadline {
        thread::yield_now();
    }
    assert_eq!(drops.load(Ordering::SeqCst), 1);
    assert_eq!(lock(&reentrant_result).as_ref().map(|result| (result.id, result.value)), Some((10, 10)));
    q.shutdown();
}

#[test]
fn running_cancel_and_generation_advance_suppress_publication() {
    for advance in [false, true] {
        let q = queue(2, 1);
        let (started_tx, started_rx) = mpsc::channel();
        enqueue(&q, 20, 1, move |token| {
            started_tx.send(()).unwrap();
            while !token.is_cancelled() { thread::yield_now(); }
            TaskOutput::success(20)
        }).unwrap();
        receive(&started_rx);
        if advance { assert_eq!(q.advance_generation(2), Ok(())); }
        else { assert_eq!(q.cancel(20), Ok(())); }
        q.shutdown();
        assert_eq!(q.poll(), None);
    }
    let q = queue(1, 1);
    assert_eq!(q.advance_generation(2), Ok(()));
    assert_eq!(q.advance_generation(2), Err(QueueError::Stale));
    assert_eq!(enqueue(&q, 21, 1, |_| TaskOutput::success(0)).unwrap_err().status, QueueError::Stale);
    let shared = Arc::new(42);
    enqueue_owned(&q, 22, 2, Arc::clone(&shared), |value, _| TaskOutput::success(**value)).unwrap();
    let deadline = std::time::Instant::now() + Duration::from_secs(3);
    let result = loop {
        if let Some(result) = q.poll() { break result; }
        assert!(std::time::Instant::now() < deadline, "shared-context completion timed out");
        thread::yield_now();
    };
    assert_eq!((result.id, result.value), (22, 42));
    q.shutdown();
}

#[test]
fn callback_failure_and_panic_are_retired_as_results() {
    let q = queue(3, 2);
    enqueue(&q, 30, 1, |_| TaskOutput::failure(-1)).unwrap();
    enqueue(&q, 31, 1, |_| -> TaskOutput { panic!("callback panic") }).unwrap();
    let mut results = Vec::new();
    for _ in 0..2 {
        let deadline = std::time::Instant::now() + Duration::from_secs(3);
        while results.len() < 2 && std::time::Instant::now() < deadline {
            if let Some(result) = q.poll() { results.push(result); }
            else { thread::yield_now(); }
        }
    }
    results.sort_by_key(|result| result.id);
    assert_eq!(results, vec![
        TaskResult { id: 30, generation: 1, succeeded: false, value: -1 },
        TaskResult { id: 31, generation: 1, succeeded: false, value: 0 },
    ]);
    q.shutdown();
}

